---@param episodeIds integer[] @see 数值表/数据表-海外/剧情表/副本剧情/A2暖雪来信活动剧情 groupId
---@param cb fun():void
function ActivityMidFestivalMainQuestPlotTool.StartPlayPlot(episodeIds, cb)
    local co = cs_coroutine.start(function()
        for _, episodeId in ipairs(episodeIds) do
            local wait = true
            local plotGo = nil
            local lastDialog = UIModule.CurrentScreen:LastDialog()
            ChapterUtils.ProcessChapter(checkNumber(episodeId), function(go)
                if lastDialog then
                    lastDialog.transform.localPosition = Vector3(9999, 9999, 9999)
                    URPCameraController:SetMainCameraActive(false)
                    UINavigationBarRoot.Instance:SetActive(false)
                    plotGo = go
                end
            end, function()
                if lastDialog then
                    lastDialog.transform.localPosition = Vector3(0, 0, 0)
                end
                URPCameraController:SetMainCameraActive(true)
                UINavigationBarRoot.Instance:SetActive(true)
                wait = false
            end)
            while wait do
                coroutine.yield(Yielders.EndOfFrame)
            end
            CfUtils.SafeDelete(plotGo)
            coroutine.yield(Yielders.EndOfFrame)
        end

        ActivityMidFestivalMgr:PlayBgMusic()
        if cb then
            cb()
        end
    end)
end

return ActivityMidFestivalMainQuestPlotTool
